import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    static Map<Long, Long> memoMap = new HashMap<>();

    static long countDigits(long x) {
        long cnt = 0;
        while (x != 0) {
            cnt++;
            x /= 10;
        }
        return cnt;
    }

    static long reverseNum(long x) {
        long[] digits = new long[17];
        int pos = 0;
        long absX = Math.abs(x);
        while (absX != 0) {
            digits[pos++] = (absX % 10);
            absX /= 10;
        }
        long res = 0;
        for (int i = pos - 1; i >= 0; i--) {
            res = res * 10 + digits[i];
        }
        return x < 0 ? -res : res;
    }

    static long previousValue(long x) {
        long c = 0;
        long orig = x;
        long absX = Math.abs(x);
        while (absX != 0) {
            c *= 10;
            c += (x < 0 ? -1 : 1);
            absX /= 10;
        }
        c = c * 10 + 1;
        return orig - c;
    }

    static long lastDigit(long x) {
        while (x >= 10 || x <= -10) {
            x /= 10;
        }
        return x;
    }

    static long deleteLeading(long x) {
        long[] digits = new long[17];
        int p = 0;
        long absX = Math.abs(x);
        while (absX >= 10) {
            digits[p++] = absX % 10;
            absX /= 10;
        }
        long res = 0;
        for (int i = p - 1; i >= 0; i--) {
            res = res * 10 + digits[i];
        }
        return x < 0 ? -res : res;
    }

    static long solve(long x) {
        if (x <= 11) {
            return Math.min(13 - x, x);
        }
        if (memoMap.containsKey(x))
            return memoMap.get(x);
        long n = 0, t = 1;
        while (t < x) {
            t = t * 10 + 1;
            n++;
        }
        if (x * 2 >= t) {
            long res = Math.min(solve(t - x) + n + 1, (x / (t / 10)) * n + solve(x % (t / 10)));
            memoMap.put(x, res);
            return res;
        } else {
            long res = (x / (t / 10)) * n + solve(x % (t / 10));
            memoMap.put(x, res);
            return res;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long a = sc.nextLong();
        System.out.println(solve(a));
        sc.close();
    }
}
